// Compose an Anthropic Messages API request.
// System = docs/ASSISTANT-CORE.md (role + ops protocol) + docs/LLM-AUTHORING.md
// (the live spec), both fetched fresh from GitHub Pages and prompt-cached so
// repeat calls inside the cache window don't re-pay for them. Model settings
// come from the Model node - the only place to touch when switching models.
const core = String($('Fetch core prompt').first().json.data || '');
const spec = String($('Fetch authoring spec').first().json.data || '');
const cfg = $('Model').first().json;
const req = $('Webhook').first().json.body || {};

// history: text turns, consecutive same-role turns merged, starting on a user turn
const messages = [];
for (const t of req.history || []) {
  if (!t || !t.text) continue;
  const role = t.role === 'assistant' ? 'assistant' : 'user';
  if (!messages.length && role === 'assistant') continue;
  const last = messages[messages.length - 1];
  if (last && last.role === role) last.content += '\n\n' + String(t.text);
  else messages.push({ role, content: String(t.text) });
}
const text = 'CURRENT GRAPH (weft format 2):\n' + JSON.stringify(req.graph || { nodes: [], wires: [] })
  + '\n\nSELECTED NODE IDS: ' + JSON.stringify(req.selection || [])
  + '\n\nLIVE EVAL ERRORS: ' + JSON.stringify(req.errors || {})
  + '\n\nUSER MESSAGE:\n' + String(req.message || '');
const content = [];
if (cfg.vision === true && typeof req.snapshot === 'string' && req.snapshot.indexOf('data:image/jpeg;base64,') === 0) {
  content.push({ type: 'image', source: { type: 'base64', media_type: 'image/jpeg', data: req.snapshot.split(',')[1] } });
}
content.push({ type: 'text', text });
const last = messages[messages.length - 1];
if (last && last.role === 'user') last.content = [{ type: 'text', text: last.content }].concat(content);
else messages.push({ role: 'user', content });

const body = {
  model: cfg.model,
  max_tokens: Number(cfg.max_tokens) || 32000,
  thinking: { type: 'adaptive' },
  output_config: { effort: cfg.effort || 'high' },
  // on a safety refusal the API retries on a fallback model by itself (beta header on the Claude node)
  fallbacks: 'default',
  system: [
    { type: 'text', text: core },
    { type: 'text', text: 'AUTHORITATIVE WEFT AUTHORING SPEC (node types, ports, list semantics):\n\n' + spec, cache_control: { type: 'ephemeral' } }
  ],
  messages
};
return [{ json: { body } }];

// A failed call (with "continue on error" the HTTP node hands us json.error
// instead of throwing): say what happened in the panel, in words.
if ($json.error && !$json.content) {
  const e = $json.error;
  const msg = typeof e === 'string' ? e : (e.message || e.description || JSON.stringify(e));
  const code = String((e && (e.httpCode || e.status || e.code)) || (msg.match(/\b(4\d\d|5\d\d)\b/) || [])[1] || '');
  let reply;
  if (/credit balance/i.test(msg)) reply = '(the Anthropic account is out of credits - top it up at console.anthropic.com/settings/billing)';
  else if (code === '529' || code === '503' || code === '502' || code === '504' || code === '500') reply = '(Claude is overloaded or the call timed out (' + code + ') - try again in a moment; if it repeats, ask for a smaller step or molt the chat)';
  else if (code === '429') reply = '(the Anthropic API is rate-limiting us (429) - wait a moment and try again)';
  else if (code === '401' || code === '403') reply = '(the Anthropic API refused the key (' + code + ') - check the Anthropic API key credential in n8n)';
  else reply = '(the model call failed' + (code ? ' (' + code + ')' : '') + ': ' + msg.slice(0, 300) + ')';
  return [{ json: { reply, ops: null, model: '', finish: 'error', error: code || 'error' } }];
}

// Split the model's answer into reply text + the weft-ops block (if any).
// Tolerates JS-isms (// comments, trailing commas) - mirrors WeftOps.tidyJSON
// in js/ops.js. If the block still won't parse, ops is null and the fence
// stays in the reply so the panel gets a go.
const stop = $json.stop_reason || '';
const text = ($json.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n');
const tidy = s => {
  let out = '', inStr = false, i = 0;
  while (i < s.length) {
    const c = s[i];
    if (inStr) { out += c; if (c === '\\') { out += s[i + 1] || ''; i += 2; continue; } if (c === '"') inStr = false; i++; }
    else if (c === '"') { inStr = true; out += c; i++; }
    else if (c === '/' && s[i + 1] === '/') { while (i < s.length && s[i] !== '\n') i++; }
    else if (c === '/' && s[i + 1] === '*') { const j = s.indexOf('*/', i + 2); i = j < 0 ? s.length : j + 2; }
    else { out += c; i++; }
  }
  return out.replace(/,(\s*[\]}])/g, '$1');
};
const pick = p => Array.isArray(p) ? p : (p && Array.isArray(p.ops) ? p.ops : null);
let reply = text.trim();
let ops = null;
const m = text.match(/```(?:weft-ops|json)?[ \t]*\n([\s\S]*?)```/);
if (m) {
  try { ops = pick(JSON.parse(m[1])); } catch (e) { try { ops = pick(JSON.parse(tidy(m[1]))); } catch (e2) { ops = null; } }
  if (ops) reply = text.replace(m[0], '').trim();
}
if (stop === 'refusal') reply = (reply ? reply + '\n\n' : '') + '(the model declined this one - try rewording the ask)';
else if (!text.trim()) reply = '(the model came back with no answer' + (stop === 'max_tokens' ? ' - it spent the whole output budget thinking; ask for a smaller step, or raise max_tokens / lower effort in the Model node' : '') + ')';
else if (stop === 'max_tokens' && !ops) reply += '\n\n(the model ran out of output tokens mid-answer - try again or ask for a smaller change)';
return [{ json: { reply, ops, model: $json.model || '', finish: stop } }];
